// Part: room: back hall morning room (plan.md ROOMS, floor y4, air y4..9, interior x39..43 x z54..60).
// Focal piece: a tea table (dark oak fence post with a slab top) between two chairs (dark oak stairs), set in line with
// the north doorway. Two moss-block plant stands carry flowering azaleas in the far corners. Light: two lanterns on
// chains from the upper floor, one over each side of the table, so the feet stay lit and the table is the brightest spot.
// Lanes: x39 and x43 stay clear from the north doorway (z53) to the living-room opening (z61), and the table's north
// and south cells stay open.
import { layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // Rows run along +z (z54..z60), columns along +x (x39..x43). One layer per y: floor row y4, table top y5.
  const legend = {
    M: "moss_block", // plant stand base on the floor
    a: "flowering_azalea", // plant on the moss block
    F: "dark_oak_fence", // table leg
    S: ["dark_oak_slab", { type: "bottom" }], // table top, sits on the leg's head
    L: ["dark_oak_stairs", { facing: "west", half: "bottom" }], // chair west of the table, back to the wall
    R: ["dark_oak_stairs", { facing: "east", half: "bottom" }], // chair east of the table, back to the wall
  };
  const floor = [
    "M....", // z54: plant stand NW (x39), clear over the north doorway
    ".....", // z55
    ".....", // z56
    ".LFR.", // z57: the tea table with its two chairs
    ".....", // z58
    ".....", // z59
    "....M", // z60: plant stand SE (x43), clear over the living-room opening
  ];
  const top = [
    "a....", // z54: azalea over the NW stand
    ".....",
    ".....",
    "..S..", // z57: the table top
    ".....",
    ".....",
    "....a", // z60: azalea over the SE stand
  ];
  layers(g, [39, 4, 54], legend, [floor, top]);

  // Two lanterns hung from chains off the upper floor (y10), 4 blocks above the floor, one over each half of the room.
  for (const [x, z] of [[40, 55], [42, 59]]) {
    g.set(x, 9, z, ...B.chain("y"));
    g.set(x, 8, z, ...B.lantern(true));
  }
}

